def int_to_mini_roman(number):
    """
    Given a positive integer or a string representing a positive integer (1 <= num <= 1000 or string length <= 1000),
    return its Roman numeral equivalent as a lowercase string.

    The function does not use loops or recursion, and runs in O(1) time by handling only up to 1000.
    If the input is a string longer than 4 digits or representing a number > 1000, the function converts each digit
    to its Roman numeral equivalent independently, preserving original order.

    Examples:
    >>> int_to_mini_roman(19) == 'xix'
    >>> int_to_mini_roman('152') == 'clii'
    >>> int_to_mini_roman(426) == 'cdxxvi'
    """
    # Map for digits in each place (thousands, hundreds, tens, ones)
    THOUSANDS = { '0':'', '1':'m' }
    HUNDREDS  = { '0':'', '1':'c', '2':'cc', '3':'ccc', '4':'cd', '5':'d', '6':'dc', '7':'dcc', '8':'dccc', '9':'cm' }
    TENS      = { '0':'', '1':'x', '2':'xx', '3':'xxx', '4':'xl', '5':'l', '6':'lx', '7':'lxx', '8':'lxxx', '9':'xc' }
    ONES      = { '0':'', '1':'i', '2':'ii', '3':'iii', '4':'iv', '5':'v', '6':'vi', '7':'vii', '8':'viii', '9':'ix' }

    # Convert input to string
    s = str(number)

    # If input is integer or string representing number <= 1000, standard conversion:
    try:
        num = int(s)
        if 1 <= num <= 1000:
            # Pad to 4 digits to access places easily
            s = f"{num:04d}"
            return (THOUSANDS[s[0]] + HUNDREDS[s[1]] + TENS[s[2]] + ONES[s[3]]).lower()
    except:
        pass

    # Otherwise, convert each digit independently to Roman numeral (no place value),
    # preserving order
    # Map single digits to roman numerals (ones place)
    SINGLE_DIGIT_ROMAN = {
        '0':'', '1':'i', '2':'ii', '3':'iii', '4':'iv', '5':'v',
        '6':'vi', '7':'vii', '8':'viii', '9':'ix'
    }
    return ''.join(SINGLE_DIGIT_ROMAN.get(ch, '') for ch in s).lower()
