def encrypt(s):
    result = []
    for char in s:
        if char.isalpha():
            base = ord('a') if char.islower() else ord('A')
            # shift forward by 4 positions, wrap around using modulo 26
            shifted = (ord(char) - base + 4) % 26 + base
