        return 0
    m, n = len(grid), len(grid[0])
    # dp[i][j] will hold max gold collected starting from (0,0) and reaching (i,j)
    dp = [[float('-inf')] * n for _ in range(m)]
    dp[0][0] = grid[0][0]

    for j in range(n-1):
        for i in range(m):
            if dp[i][j] == float('-inf'):
                continue
            # Move right (i, j+1)
            dp[i][j+1] = max(dp[i][j+1], dp[i][j] + grid[i][j+1])
            # Move right-up (i-1, j+1)
            if i-1 >= 0:
                dp[i-1][j+1] = max(dp[i-1][j+1], dp[i][j] + grid[i-1][j+1])
            # Move right-down (i+1, j+1)
            if i+1 < m:
                dp[i+1][j+1] = max(dp[i+1][j+1], dp[i][j] + grid[i+1][j+1])

    return max(dp[i][n-1] for i in range(m) if dp[i][n-1] != float('-inf'))
