def set_left_most_unset_bit(n: int) -> int:
    if n == 0:
        return 1  # The leftmost unset bit of 0 is bit 0

    bit_length = n.bit_length()
    # If all bits up to bit_length are set, set the new highest bit (bit_length)
    if (1 << bit_length) - 1 == n:
        return n | (1 << bit_length)

    # Otherwise, find the leftmost unset bit within bit_length
    for i in reversed(range(bit_length)):
        if not (n & (1 << i)):
            return n | (1 << i)
